-- Locales/deDE.lua
-- German (deDE) translations for EQ Objective Tracker.
--
-- GENERATED from the shared translation store. Do not hand-edit: translate in the
-- EverythingLocales repo instead, which feeds every addon in the family.
--
-- NOTE: do NOT add an @localization@ packager token here. It fails the CurseForge
-- build with errorCode 1002 on a project without localization enabled. Translations
-- are bundled directly as the L["..."] lines below.

if GetLocale() ~= "deDE" then return end

local _, ns = ...
local L = ns.L

-- Options/TabGeneral.lua
L["General"] = "Allgemein"
L["Lock tracker"] = "Tracker sperren"
L["Disable drag-to-move and resize."] = "Verschieben und Ändern der Größe per Ziehen deaktivieren."
L["Hide tracker in combat"] = "Tracker im Kampf ausblenden"
L["Hides the tracker while you are in combat and brings it back when you leave."] = "Blendet den Tracker während des Kampfes aus und zeigt ihn wieder an, sobald du den Kampf verlässt."
L["Hide tracker in instances"] = "Tracker in Instanzen ausblenden"
L["Raids, dungeons, delves."] = "Schlachtzüge, Dungeons, Tiefen."
L["Hide tracker when world map is open"] = "Tracker bei geöffneter Weltkarte ausblenden"
L["Hides the tracker while the world map is up, so it does not sit over the map."] = "Blendet den Tracker bei geöffneter Weltkarte aus, damit er nicht über der Karte liegt."
L["Hide tracker in Mythic+"] = "Tracker in Mythisch+ ausblenden"
L["Hides the tracker during an active Mythic+ run, then brings it back when the run ends."] = "Blendet den Tracker während eines aktiven Mythisch+-Laufs aus und zeigt ihn wieder an, sobald der Lauf endet."
L["Auto-track accepted quests"] = "Angenommene Quests automatisch verfolgen"
L["Matches Blizzard's default."] = "Entspricht der Blizzard-Standardeinstellung."
L["Keep focused quest after relog"] = "Fokussierte Quest nach erneuter Anmeldung beibehalten"
L["Restores the waypoint arrow."] = "Stellt den Wegpfeil wieder her."
L["Hide Questie's quest tracker"] = "Questie-Questtracker ausblenden"
L["Hides Questie's tracker frame while EQ Objective Tracker is running. It only hides the frame, and Questie's own disable path is never called."] = "Blendet das Trackerfenster von Questie aus, solange der EQ Objective Tracker läuft. Es wird nur das Fenster ausgeblendet, Questies eigene Deaktivierung wird nie aufgerufen."
L["Options Window Scale"] = "Skalierung des Optionsfensters"
L["Resizes this EQ Objective Tracker options window only. It does not change the quest tracker or anything shown in the game world. The new size applies when you let go of the slider."] = "Ändert nur die Größe dieses Optionsfensters des EQ Objective Trackers. Der Questtracker oder andere Anzeigen in der Spielwelt werden dadurch nicht verändert. Die neue Größe wird übernommen, sobald du den Regler loslässt."
L["Reset position and size"] = "Position und Größe zurücksetzen"
L["Returns the tracker to its default position and size."] = "Setzt den Tracker auf seine Standardposition und -größe zurück."
L["Reset all settings"] = "Alle Einstellungen zurücksetzen"
L["Reset every EQ Objective Tracker setting to defaults? The interface will reload."] = "Alle Einstellungen des EQ Objective Trackers auf die Standardwerte zurücksetzen? Die Benutzeroberfläche wird neu geladen."
L["Reset"] = "Zurücksetzen"
L["Cancel"] = "Abbrechen"
L["Restores every setting on every tab to its default and reloads the interface. This also clears the Options Window Scale, which every character shares, and this character's collapsed sections and individually hidden entries."] = "Setzt alle Einstellungen auf jedem Tab auf ihre Standardwerte zurück und lädt die Benutzeroberfläche neu. Dadurch wird auch die Skalierung des Optionsfensters zurückgesetzt, die von allen Charakteren gemeinsam verwendet wird, sowie die eingeklappten Abschnitte und individuell ausgeblendeten Einträge dieses Charakters."
L["Profiles"] = "Profile"
L["Switching profiles reloads the UI. Profiles are shared across characters. Use them to keep different setups such as raid and solo. |cffEBB706New Profile|r prompts for a name and creates it on the spot."] = "Beim Wechseln des Profils wird die Benutzeroberfläche neu geladen. Profile werden von allen Charakteren gemeinsam verwendet. Nutze sie, um verschiedene Konfigurationen wie Schlachtzug und Solo zu speichern. |cffEBB706New Profile|r fordert dich zur Eingabe eines Namens auf und erstellt das Profil sofort."
L["Active profile"] = "Aktives Profil"
L["Switches to another saved settings profile. The interface reloads immediately when you pick one."] = "Wechselt zu einem anderen gespeicherten Einstellungsprofil. Die Benutzeroberfläche wird sofort neu geladen, sobald du eines auswählst."
L["New Profile"] = "Neues Profil"
L["Profile name:"] = "Profilname:"
L["Create"] = "Erstellen"
L["Overwrite profile?"] = "Profil überschreiben?"
L["A profile named \"%s\" already exists. Overwrite it with a copy of your current settings?"] = "Ein Profil mit dem Namen \"%s\" existiert bereits. Soll es mit einer Kopie deiner aktuellen Einstellungen überschrieben werden?"
L["Overwrite"] = "Überschreiben"
L["Prompts for a name, then creates a profile holding a copy of your current settings and switches to it. The interface reloads."] = "Fordert dich zur Eingabe eines Namens auf, erstellt anschließend ein Profil mit einer Kopie deiner aktuellen Einstellungen und wechselt zu diesem Profil. Die Benutzeroberfläche wird neu geladen."

-- Options/TabTracker.lua
L["Zone"] = "Gebiet"
L["Groups entries under the heading they sit under in your quest log."] = "Gruppiert Einträge unter der Überschrift, unter der sie in deinem Questlog stehen."
L["Title"] = "Titel"
L["Alphabetical by name."] = "Alphabetisch nach Name."
L["Status"] = "Status"
L["Puts everything that is ready to turn in at the top."] = "Setzt alles, was zur Abgabe bereit ist, nach oben."
L["Type"] = "Typ"
L["Weekly first, then daily, then everything else. Only quests carry a type, so other sections fall back to alphabetical."] = "Zuerst wöchentlich, dann täglich, anschließend alles andere. Nur Quests haben einen Typ, daher werden andere Abschnitte alphabetisch sortiert."
L["Level"] = "Stufe"
L["Lowest quest level first."] = "Niedrigste Queststufe zuerst."
L["Distance"] = "Entfernung"
L["Nearest objective first, updated as you move. A quest ready to turn in measures to its turn-in point."] = "Nächstgelegenes Ziel zuerst, aktualisiert während du dich bewegst. Bei einer zur Abgabe bereiten Quest wird die Entfernung zum Abgabeort gemessen."
L["Recent"] = "Zuletzt angenommen"
L["Most recently accepted first."] = "Zuletzt angenommene zuerst."
L["Manual"] = "Manuell"
L["Your own order. Drag quests up and down in the tracker to set it."] = "Deine eigene Reihenfolge. Ziehe Quests im Tracker nach oben oder unten, um sie festzulegen."
L["Quests the game resets on its own schedule rather than daily or weekly. Special Assignments and some meta quests are what you will see here."] = "Quests, die das Spiel nach seinem eigenen Zeitplan zurücksetzt und nicht täglich oder wöchentlich. Hier findest du Sonderaufträge und einige Metaquests."
L["Campaign section"] = "Kampagnenabschnitt"
L["Quests section"] = "Questabschnitt"
L["Profession section"] = "Berufsabschnitt"
L["Endeavors section"] = "Unterfangen-Abschnitt"
L["Achievements section"] = "Erfolgeabschnitt"
L["World Quests section"] = "Weltquestabschnitt"
L["Top"] = "Oben"
L["Bottom"] = "Unten"
L["Move %s up"] = "%s nach oben verschieben"
L["Move %s down"] = "%s nach unten verschieben"
L["Reorders where this section sits in the tracker. A section only shows while it has something in it, so empty sections won't visibly move."] = "Ändert die Position dieses Abschnitts im Tracker. Ein Abschnitt wird nur angezeigt, wenn er Einträge enthält, daher ist bei leeren Abschnitten keine sichtbare Bewegung möglich."
L["Tracker"] = "Tracker"
L["On-Screen Tracker"] = "Bildschirmtracker"
L["Changes apply immediately to the on-screen tracker."] = "Änderungen werden sofort auf den Bildschirmtracker angewendet."
L["Show only tracked quests"] = "Nur verfolgte Quests anzeigen"
L["Hides quests that are in your log but not tracked. Matches Blizzard's default tracker."] = "Blendet Quests aus, die sich in deinem Questlog befinden, aber nicht verfolgt werden. Entspricht dem Blizzard-Standardtracker."
L["Simplify Mode"] = "Vereinfachter Modus"
L["Show only the first incomplete objective per quest."] = "Nur das erste nicht abgeschlossene Ziel pro Quest anzeigen."
L["Simplify tracked achievements"] = "Verfolgte Erfolge vereinfachen"
L["Show only incomplete criteria for tracked achievements."] = "Nur nicht erfüllte Kriterien für verfolgte Erfolge anzeigen."
L["Sort Order"] = "Sortierreihenfolge"
L["Drag and drop the quests in the tracker to reorder them however you like."] = "Ziehe die Quests im Tracker per Drag-and-drop, um sie nach Belieben neu anzuordnen."
L["Filters"] = "Filter"
L["Show or hide this category of entry in the tracker."] = "Diese Kategorie von Einträgen im Tracker anzeigen oder ausblenden."
L["Show only quests in current zone"] = "Nur Quests im aktuellen Gebiet anzeigen"
L["Only show entries with an objective on your current map. Entries whose provider cannot tell are always shown."] = "Nur Einträge mit einem Ziel auf deiner aktuellen Karte anzeigen. Einträge, bei denen der Anbieter dies nicht feststellen kann, werden immer angezeigt."
L["Reset filters to defaults"] = "Filter auf Standardwerte zurücksetzen"
L["Turns every category filter back on and clears the current-zone filter. Nothing else on this tab is changed."] = "Schaltet alle Kategoriefilter wieder ein und hebt den Filter für das aktuelle Gebiet auf. Sonst wird auf diesem Reiter nichts verändert."
L["Tracker Visibility"] = "Sichtbarkeit des Trackers"
L["Uncheck to hide this section from the tracker even while it has entries."] = "Deaktiviere die Option, um diesen Abschnitt im Tracker auszublenden, auch wenn er Einträge enthält."
L["Auto-list current-zone world quests"] = "Weltquests des aktuellen Gebiets automatisch auflisten"
L["Lists every WQ in your zone without tracking each."] = "Listet jede Weltquest in deinem Gebiet auf, ohne sie einzeln zu verfolgen."
L["Set a custom World Quests height"] = "Benutzerdefinierte Höhe für Weltquests festlegen"
L["By default the World Quests area is capped to a share of the tracker, set by the slider below that. Turn this on to give it a fixed height in pixels instead."] = "Standardmäßig ist der Bereich für Weltquests auf einen Anteil des Trackers begrenzt, der mit dem darunterliegenden Regler festgelegt wird. Aktiviere diese Option, um stattdessen eine feste Höhe in Pixeln festzulegen."
L["World Quests Height"] = "Höhe der Weltquests"
L["Height in pixels for the world quest area. Only used while Set a custom World Quests height is on."] = "Höhe des Weltquestbereichs in Pixeln. Wird nur verwendet, wenn „Benutzerdefinierte Höhe für Weltquests festlegen“ aktiviert ist."
L["Maximum Height (percent of tracker)"] = "Maximale Höhe (Prozent des Trackers)"
L["The most of the tracker the world quest area may take. It is capped here first and your quest list takes the space that is left, scrolling for whatever does not fit. Only used while Set a custom World Quests height is off."] = "Der maximale Anteil des Trackers, den der Weltquestbereich einnehmen darf. Hier wird er zuerst begrenzt, und deine Questliste erhält den verbleibenden Platz. Alles, was nicht hineinpasst, wird durch Scrollen erreichbar. Wird nur verwendet, wenn „Benutzerdefinierte Höhe für Weltquests festlegen“ deaktiviert ist."
L["Section Order"] = "Abschnittsreihenfolge"
L["Rearrange the tracker's sections with the arrows below. A section only appears on the tracker while it has something in it, so reordering an empty section won't look like anything changed. World Quests scroll in their own panel and can only sit at the very top or bottom, so use the Top/Bottom control."] = "Ordne die Abschnitte des Trackers mit den Pfeilen unten neu an. Ein Abschnitt wird im Tracker nur angezeigt, wenn er Einträge enthält, daher ist bei einem leeren Abschnitt keine sichtbare Änderung zu erkennen. Weltquests werden in einem eigenen Bereich gescrollt und können nur ganz oben oder ganz unten stehen. Verwende dafür die Steuerung „Oben/Unten“."
L["World Quests Position"] = "Position der Weltquests"
L["Where the World Quests panel sits on the tracker. |cffffffffTop|r puts it above your quests. |cffffffffBottom|r keeps it below your quests, which is the default. World Quests scroll in their own capped panel, which is why they can't be mixed in between the other sections."] = "Legt fest, wo der Weltquestbereich im Tracker angezeigt wird. |cffffffffTop|r platziert ihn über deinen Quests. |cffffffffBottom|r belässt ihn unter deinen Quests, was der Standard ist. Weltquests werden in einem eigenen begrenzten Bereich gescrollt und können daher nicht zwischen den anderen Abschnitten platziert werden."
L["Options"] = "Optionen"
L["Quest Title Color By Difficulty"] = "Questtitelfarbe nach Schwierigkeitsgrad"
L["Colors each quest title by how hard it is for your level, the way the quest log does. The Quest Title Color Override on the Appearance tab wins over this while it is set."] = "Färbt jeden Questtitel entsprechend seinem Schwierigkeitsgrad für deine Stufe, wie im Questlog. Die Überschreibung der Questtitelfarbe im Tab „Erscheinungsbild“ hat Vorrang, solange sie festgelegt ist."
L["Show quest level prefix"] = "Queststufenpräfix anzeigen"
L["For example, [60] Title."] = "Zum Beispiel [60] Titel."
L["Show zone label under quest titles"] = "Gebietsbezeichnung unter Questtiteln anzeigen"
L["Adds the quest log heading each quest came from as a small line under its title."] = "Fügt unter dem Titel jeder Quest die Überschrift aus dem Questlog als kleine Zeile hinzu."
L["Show objective progress numbers"] = "Fortschrittszahlen der Ziele anzeigen"
L["For example, 0/4, 1/1, etc."] = "Zum Beispiel 0/4, 1/1 usw."
L["Show progress bars"] = "Fortschrittsbalken anzeigen"
L["Draws a filled bar for objectives that report a percentage or a running total, the way the default tracker does, instead of a plain line of text. Applies to quests, World Quests, achievements and scenario objectives."] = "Zeichnet für Ziele, die einen Prozentwert oder einen laufenden Zähler melden, einen gefüllten Balken statt einer reinen Textzeile - so wie der Standardtracker. Gilt für Quests, Weltquests, Erfolge und Szenarioziele."
L["Show quest ID"] = "Quest-ID anzeigen"
L["Useful for bug reports."] = "Nützlich für Fehlermeldungen."
L["Show the visible / total count on section headers"] = "Anzahl sichtbar / insgesamt in Abschnittsüberschriften anzeigen"
L["For example, 3/9. Applies to every section header."] = "Zum Beispiel 3/9. Gilt für alle Abschnittsüberschriften."
L["Show usable quest item buttons"] = "Schaltflächen für verwendbare Questgegenstände anzeigen"
L["Puts a button on the tracker row of any quest that carries a usable item, so you can use it without opening your bags."] = "Fügt in der Trackerzeile jeder Quest mit einem verwendbaren Gegenstand eine Schaltfläche hinzu, sodass du ihn verwenden kannst, ohne deine Taschen zu öffnen."
L["Show Options icon on the tracker"] = "Optionssymbol im Tracker anzeigen"
L["A small cogwheel at the top-right of the tracker that opens the options panel."] = "Ein kleines Zahnrad oben rechts im Tracker, das den Optionsbereich öffnet."
L["Show Quest Discovered popups"] = "Popups für entdeckte Quests anzeigen"
L["Boxes for newly discovered / completed quests."] = "Fenster für neu entdeckte / abgeschlossene Quests."
L["Show NEW tag on recently accepted quests"] = "„NEU“-Markierung bei kürzlich angenommenen Quests anzeigen"
L["For about an hour after accepting."] = "Etwa eine Stunde nach dem Annehmen."
L["Split quest click"] = "Questklick aufteilen"
L["Click the icon to focus, click the title to open the quest log."] = "Klicke auf das Symbol, um die Quest zu fokussieren, oder auf den Titel, um das Questlog zu öffnen."
L["Quest Sound"] = "Questton"
L["Plays when a quest is ready to turn in."] = "Wird abgespielt, wenn eine Quest zur Abgabe bereit ist."
L["Quest Complete Sound"] = "Quest-Abschlusston"
L["Which sound plays when a quest becomes ready to turn in."] = "Legt fest, welcher Ton abgespielt wird, wenn eine Quest zur Abgabe bereit ist."
L["Scenario Bonus Objectives"] = "Bonusziele für Szenarien"
L["Show bonus objectives HUD"] = "HUD für Bonusziele anzeigen"
L["Shows a small movable checklist of the extra bonus objectives that appear during some scenarios and delves, so you do not miss their rewards. Drag to move, right-click to lock or reset. Off by default."] = "Zeigt eine kleine verschiebbare Checkliste der zusätzlichen Bonusziele an, die während einiger Szenarien und Tiefen erscheinen, damit du ihre Belohnungen nicht verpasst. Ziehen zum Verschieben, Rechtsklick zum Sperren oder Zurücksetzen. Standardmäßig deaktiviert."
L["Test"] = "Testen"
L["Draws the HUD with two made-up bonus objectives so you can position and size it without being in a scenario or delve. Click again to clear it."] = "Zeigt das HUD mit zwei erfundenen Bonuszielen an, damit du es positionieren und seine Größe anpassen kannst, ohne dich in einem Szenario oder einer Tiefe zu befinden. Erneut klicken, um es zu entfernen."
L["HUD Scale"] = "HUD-Skalierung"
L["Sizes the bonus objectives HUD."] = "Legt die Größe des Bonusziele-HUDs fest."

-- Options/TabAppearance.lua
L["None"] = "Keine"
L["Outline"] = "Umriss"
L["Thick"] = "Stärke"
L["Mono"] = "Mono"
L["Mono Outline"] = "Mono-Umrandung"
L["Mono Thick"] = "Mono-Stärke"
L["Plain"] = "Einfach"
L["Card"] = "Karte"
L["Header Bar 1"] = "Kopfleiste 1"
L["Header Bar 2"] = "Kopfleiste 2"
L["Left"] = "Links"
L["Center"] = "Mitte"
L["Right"] = "Rechts"
L["Same as tracker font"] = "Wie die Trackerschrift"
L["Appearance"] = "Darstellung"
L["Font"] = "Schriftart"
L["Fonts registered through LibSharedMedia, so anything from ElvUI or SharedMedia appears here too."] = "Über LibSharedMedia registrierte Schriftarten. Daher werden hier auch Schriftarten aus ElvUI oder SharedMedia angezeigt."
L["Font Size"] = "Schriftgröße"
L["Base size for objective text. Titles and headers offset from this."] = "Grundgröße für Zieltext. Titel und Überschriften werden davon abweichend skaliert."
L["Title Size Offset"] = "Größenabweichung der Titel"
L["Sizes quest and achievement titles separately from the objective text. This value is added to the Font Size above: 0 keeps titles the same size as the base font, positive makes them larger, negative smaller."] = "Legt die Größe von Quest- und Erfolgstiteln unabhängig vom Zieltext fest. Dieser Wert wird zur obigen Schriftgröße addiert: 0 behält die gleiche Größe wie die Grundschrift bei, positive Werte vergrößern die Titel, negative verkleinern sie."
L["Header Size Offset"] = "Größenabweichung der Überschriften"
L["Sizes the section headers (Quests, Campaign, and so on) independently of the quest text. Added on top of the Font Size above: the default 4 keeps headers at their current size, lower shrinks them (handy on a low UI scale), higher enlarges them."] = "Legt die Größe der Abschnittsüberschriften (Quests, Kampagne usw.) unabhängig vom Questtext fest. Wird zur obigen Schriftgröße addiert: Der Standardwert 4 behält die aktuelle Größe der Überschriften bei, niedrigere Werte verkleinern sie (praktisch bei niedriger UI-Skalierung), höhere Werte vergrößern sie."
L["Font Outline"] = "Schriftumriss"
L["Outlines keep small text legible over bright terrain."] = "Umrandungen sorgen dafür, dass kleine Texte auch vor hellem Gelände lesbar bleiben."
L["Text Shadow"] = "Textschatten"
L["Draws a soft drop-shadow behind all tracker text so it stays readable over bright or busy backgrounds. Use Shadow Color to tint it and Shadow Size to set how far it's cast."] = "Zeichnet einen weichen Schlagschatten hinter allen Trackertexten, damit sie vor hellen oder unruhigen Hintergründen lesbar bleiben. Verwende „Schattenfarbe“, um ihn einzufärben, und „Schattengröße“, um seine Ausdehnung festzulegen."
L["Shadow Color"] = "Schattenfarbe"
L["Shadow color and opacity."] = "Farbe und Deckkraft des Schattens."
L["Shadow Size"] = "Schattengröße"
L["How far the text drop-shadow is cast behind the letters. Higher values give a larger, more pronounced shadow. Lower values keep it tight. Only applies while Text Shadow is on."] = "Legt fest, wie weit der Textschatten hinter den Buchstaben erscheint. Höhere Werte erzeugen einen größeren, deutlich ausgeprägteren Schatten. Niedrigere Werte halten ihn kompakt. Wird nur angewendet, wenn „Textschatten“ aktiviert ist."
L["Scenario"] = "Szenario"
L["Draws a drop-shadow behind the scenario / delve banner text (the Stage and name lines). This is SEPARATE from the Text Shadow above, which affects only the quest and objective text. The banner is styled on its own."] = "Zeichnet einen Schlagschatten hinter dem Bannertext des Szenarios / der Tiefe (den Zeilen für Abschnitt und Name). Dieser ist VON „Textschatten“ oben GETRENNT und betrifft nur den Quest- und Zieltext. Das Banner wird unabhängig davon gestaltet."
L["Color and opacity of the banner's drop shadow."] = "Farbe und Deckkraft des Schattens des Banners."
L["How far the scenario banner's drop-shadow is cast. Higher values give a larger, more pronounced shadow. Lower values keep it tight. Only applies while the Scenario Text Shadow above is on."] = "Legt fest, wie weit der Schlagschatten des Szenariobanners erscheint. Höhere Werte erzeugen einen größeren, deutlich ausgeprägteren Schatten. Niedrigere Werte halten ihn kompakt. Wird nur angewendet, wenn der obige Szenariotextschatten aktiviert ist."
L["Banner Alignment"] = "Bannerausrichtung"
L["Positions the scenario / delve banner within the tracker. Left lines it up with the quest text, Center keeps it centered (the default), and Right pushes it to the tracker's right edge."] = "Legt die Position des Szenario-/Tiefenbanners innerhalb des Trackers fest. „Links“ richtet es am Questtext aus, „Mitte“ zentriert es (Standard) und „Rechts“ schiebt es an den rechten Rand des Trackers."
L["Banner Text Size"] = "Bannertextgröße"
L["Grows or shrinks the scenario / delve banner's Stage and name text. 0 is the default size. The banner artwork is a fixed size, so large values may overflow it."] = "Vergrößert oder verkleinert den Abschnitts- und Namenstext des Szenario-/Tiefenbanners. 0 ist die Standardgröße. Das Bannerbild hat eine feste Größe, daher können große Werte darüber hinausgehen."
L["Criteria Text Size"] = "Kriterientextgröße"
L["Sizes the scenario / delve objective (criteria) lines shown under the banner, separately from the Banner Text Size above. Raise it if the criteria text looks small next to your quest and World Quest text."] = "Legt die Größe der unter dem Banner angezeigten Ziel- (Kriterien-)Zeilen des Szenarios / der Tiefe unabhängig von der obigen Bannertextgröße fest. Erhöhe den Wert, wenn der Kriterientext neben deinem Quest- und Weltquesttext zu klein wirkt."
L["Scroll Bar"] = "Bildlaufleiste"
L["Hide scroll bar"] = "Bildlaufleiste ausblenden"
L["Removes the tracker's scroll bar entirely and scrolls with the mouse wheel instead. Everything else in this group styles that bar, so it all stops applying while this is on."] = "Entfernt die Bildlaufleiste des Trackers vollständig und ermöglicht stattdessen das Scrollen mit dem Mausrad. Alle anderen Einstellungen in dieser Gruppe gestalten diese Leiste und sind daher deaktiviert, solange diese Option aktiviert ist."
L["Scroll Bar Background"] = "Hintergrund der Bildlaufleiste"
L["Draws a track behind the scroll bar so it stays visible over bright terrain."] = "Zeichnet eine Spur hinter der Bildlaufleiste, damit sie vor hellem Gelände sichtbar bleibt."
L["Scroll Bar Color"] = "Farbe der Bildlaufleiste"
L["Color and opacity of the scroll bar track."] = "Farbe und Deckkraft der Spur der Bildlaufleiste."
L["Solid color thumb"] = "Griff mit Volltonfarbe"
L["Replaces the tracker scroll bar's textured thumb (the draggable block) with a flat single-color block. Use the Thumb Color and Thumb Width controls to style it. Off restores the stock Blizzard bar."] = "Ersetzt den strukturierten Griff der Tracker-Bildlaufleiste (den verschiebbaren Block) durch einen flachen Block mit einer einzigen Farbe. Verwende „Grifffarbe“ und „Griffbreite“, um ihn zu gestalten. Bei Deaktivierung wird die standardmäßige Blizzard-Leiste wiederhergestellt."
L["Thumb Color"] = "Grifffarbe"
L["Color and opacity of the draggable block. Only used while Solid color thumb is on."] = "Farbe und Deckkraft des verschiebbaren Blocks. Wird nur verwendet, wenn „Griff mit Volltonfarbe“ aktiviert ist."
L["Thumb Width"] = "Griffbreite"
L["How wide the draggable block is. Only used while Solid color thumb is on."] = "Legt fest, wie breit der verschiebbare Block ist. Wird nur verwendet, wenn „Griff mit Volltonfarbe“ aktiviert ist."
L["Hide scroll bar arrows"] = "Pfeile der Bildlaufleiste ausblenden"
L["Hides the up and down arrow buttons at the ends of the tracker scroll bar. The bar still scrolls by dragging the thumb or using the mouse wheel."] = "Blendet die Pfeilschaltflächen zum Hoch- und Herunterscrollen an den Enden der Tracker-Bildlaufleiste aus. Die Leiste kann weiterhin durch Ziehen des Griffs oder mit dem Mausrad gescrollt werden."
L["Background"] = "Hintergrund"
L["Fills the tracker behind the text. Useful over bright terrain."] = "Füllt den Bereich hinter dem Text im Tracker aus. Nützlich vor hellem Gelände."
L["Background Color"] = "Hintergrundfarbe"
L["Background color and opacity."] = "Hintergrundfarbe und Deckkraft."
L["Border"] = "Rahmen"
L["Draws a border around the tracker."] = "Zeichnet einen Rand um den Tracker."
L["Border Color"] = "Rahmenfarbe"
L["Border color and opacity."] = "Randfarbe und Deckkraft."
L["Border Thickness"] = "Randstärke"
L["Border thickness in pixels."] = "Randstärke in Pixeln."
L["Header Bar"] = "Kopfleiste"
L["Show header bars"] = "Kopfleisten anzeigen"
L["Draws a colored gradient bar behind each section header (Quests, Campaign, World Quests, and so on), for a look closer to the default Blizzard tracker. Off by default."] = "Zeichnet hinter jeder Abschnittsüberschrift (Quests, Kampagne, Weltquests usw.) eine farbige Verlaufsleiste, um dem standardmäßigen Blizzard-Tracker ähnlicher zu sehen. Standardmäßig deaktiviert."
L["Bar Color"] = "Leistenfarbe"
L["Brightest end of the bar gradient. The other end is the same color darkened."] = "Hellstes Ende des Farbverlaufs der Leiste. Das andere Ende verwendet dieselbe Farbe in abgedunkelter Form."
L["Bar Style"] = "Leistenstil"
L["Header Bar 1 is a horizontal gradient (bright on the left, dark on the right). Header Bar 2 is a vertical gradient (bright at the top, dark at the bottom). Bar Color, Bar Height, and Soft edges all apply to whichever style you pick."] = "Kopfleiste 1 ist ein horizontaler Verlauf (hell links, dunkel rechts). Kopfleiste 2 ist ein vertikaler Verlauf (hell oben, dunkel unten). Leistenfarbe, Leistenhöhe und Weiche Kanten gelten für den ausgewählten Stil."
L["Soft edges"] = "Weiche Kanten"
L["Feathers the top, left, and right edges of the header bar so it blends into the UI instead of sitting in a hard box. The gradient color is unchanged. Only applies while Header bars is on. Off by default."] = "Blendet die oberen, linken und rechten Kanten der Kopfleiste weich aus, sodass sie sich in die UI einfügt, anstatt in einem harten Kasten zu stehen. Die Verlaufsfarbe bleibt unverändert. Wird nur angewendet, wenn „Kopfleisten anzeigen“ aktiviert ist. Standardmäßig deaktiviert."
L["Bar Height"] = "Leistenhöhe"
L["How tall the section-header bar is. The bar is centered on the header row, so larger values fill more of it."] = "Legt die Höhe der Abschnittsüberschriftenleiste fest. Die Leiste ist in der Überschriftenzeile zentriert, sodass größere Werte mehr davon ausfüllen."
L["Edge Softness"] = "Kantenglättung"
L["How soft the header bar's feathered edges are when Soft edges is on. Higher is softer, lower tightens toward a hard edge."] = "Legt fest, wie weich die ausgeblendeten Kanten der Kopfleiste bei aktivierten weichen Kanten sind. Höhere Werte machen sie weicher, niedrigere Werte nähern sie einem harten Rand an."
L["Colors & Dimensions"] = "Farben & Abmessungen"
L["Reset to Defaults"] = "Auf Standardwerte zurücksetzen"
L["Reset every setting on this tab to its defaults? The interface will reload."] = "Alle Einstellungen dieses Tabs auf ihre Standardwerte zurücksetzen? Das Interface wird neu geladen."
L["Restores every control on this tab, including the zone bar block, to its default. Other tabs are left alone."] = "Setzt alle Einstellungen dieses Tabs einschließlich des Gebietsleistenblocks auf ihre Standardwerte zurück. Andere Tabs bleiben unverändert."
L["Quest Title Color Override"] = "Überschreibung der Questtitelfarbe"
L["When cleared, falls back to difficulty coloring or default yellow."] = "Wenn keine Farbe festgelegt ist, wird die Schwierigkeitsfärbung oder das standardmäßige Gelb verwendet."
L["Use class color for titles"] = "Klassenfarbe für Titel verwenden"
L["Colors quest, achievement, and endeavor titles with the class color of the character you are currently logged in on. Overrides the color above while it is on. Off by default."] = "Färbt Quest-, Erfolgs- und Unterfangenstitel mit der Klassenfarbe des Charakters, mit dem du aktuell eingeloggt bist. Überschreibt die obige Farbe, solange diese Option aktiviert ist. Standardmäßig deaktiviert."
L["Use title color for completed quests"] = "Titelfarbe für abgeschlossene Quests verwenden"
L["Instead of green."] = "Statt Grün."
L["Section Header Color"] = "Farbe der Abschnittsüberschriften"
L["Color of the Quests, Campaign and World Quests headings."] = "Farbe der Überschriften für Quests, Kampagne und Weltquests."
L["Use class color for headers"] = "Klassenfarbe für Überschriften verwenden"
L["Colors the section headers (Quests, Campaign, and so on) with the class color of the character you are currently logged in on. Overrides the color above while it is on. Off by default."] = "Färbt die Abschnittsüberschriften (Quests, Kampagne usw.) mit der Klassenfarbe des Charakters, mit dem du aktuell eingeloggt bist. Überschreibt die obige Farbe, solange diese Option aktiviert ist. Standardmäßig deaktiviert."
L["Divider Line Color"] = "Farbe der Trennlinie"
L["Sets the color of the thin line under each section header. Defaults to the original gold."] = "Legt die Farbe der dünnen Linie unter jeder Abschnittsüberschrift fest. Standardmäßig wird das ursprüngliche Gold verwendet."
L["Tracker Scale"] = "Trackerskalierung"
L["Scales the whole tracker. Takes effect immediately out of combat."] = "Skaliert den gesamten Tracker. Wird außerhalb des Kampfes sofort angewendet."
L["Block Spacing"] = "Blockabstand"
L["Vertical gap between each entry and between sections."] = "Vertikaler Abstand zwischen den einzelnen Einträgen und zwischen den Abschnitten."
L["Line Spacing"] = "Zeilenabstand"
L["Adds vertical space between a quest's objective lines, across the whole tracker. 0 keeps the default spacing."] = "Fügt im gesamten Tracker vertikalen Abstand zwischen den Zielzeilen einer Quest hinzu. 0 behält den Standardabstand bei."
L["Header Spacing"] = "Überschriftenabstand"
L["Adds or removes space around section headers and beneath each quest's title. 0 keeps the default spacing."] = "Fügt um Abschnittsüberschriften und unter dem Titel jeder Quest Abstand hinzu oder entfernt ihn. 0 behält den Standardabstand bei."
L["Quest Rows"] = "Questzeilen"
L["Row Layout"] = "Zeilenlayout"
L["How each quest is drawn in the tracker. |cffffffffPlain|r is the default look - text straight on the tracker background. |cffffffffCard|r gives every quest its own panel with a background and border, which makes long lists easier to read apart."] = "Legt fest, wie jede Quest im Tracker dargestellt wird. |cffffffffPlain|r ist die Standarddarstellung – Text direkt auf dem Trackerhintergrund. |cffffffffCard|r gibt jeder Quest einen eigenen Bereich mit Hintergrund und Rand, wodurch lange Listen leichter voneinander zu unterscheiden sind."
L["Fill color behind each quest card. Only used while Row Layout is set to Card."] = "Füllfarbe hinter jeder Questkarte. Wird nur verwendet, wenn das Zeilenlayout auf Karte gesetzt ist."
L["Outline color around each quest card. Only used while Row Layout is set to Card."] = "Umrandungsfarbe jeder Questkarte. Wird nur verwendet, wenn das Zeilenlayout auf Karte gesetzt ist."
L["How thick the card outline is, in pixels. 0 hides the outline and leaves just the fill."] = "Legt die Stärke der Kartenumrandung in Pixeln fest. 0 blendet die Umrandung aus und lässt nur die Füllung bestehen."
L["Card Padding"] = "Karteninnenabstand"
L["Breathing room between a card's edge and the text inside it. Larger values make taller cards."] = "Abstand zwischen dem Rand einer Karte und dem darin enthaltenen Text. Größere Werte machen die Karten höher."
L["Tint cards by quest type"] = "Karten nach Questtyp einfärben"
L["Gives campaign, legendary, dungeon and raid entries their own card color. Anything else uses the plain background color above."] = "Verleiht Einträgen aus Kampagne, legendären Quests, Dungeons und Schlachtzügen eine eigene Kartenfarbe. Alles andere verwendet die oben festgelegte einfache Hintergrundfarbe."
L["Campaign"] = "Kampagne"
L["Card color for campaign entries. Needs Tint cards by quest type switched on."] = "Kartenfarbe für Kampagneneinträge. Erfordert die Aktivierung von „Karten nach Questtyp einfärben“."
L["Legendary"] = "Legendär"
L["Card color for legendary entries. Needs Tint cards by quest type switched on."] = "Kartenfarbe für legendäre Einträge. Erfordert die Aktivierung von „Karten nach Questtyp einfärben“."
L["Dungeon"] = "Dungeon"
L["Card color for dungeon entries. Needs Tint cards by quest type switched on."] = "Kartenfarbe für Dungeon-Einträge. Erfordert die Aktivierung von „Karten nach Questtyp einfärben“."
L["Raid"] = "Schlachtzug"
L["Card color for raid entries. Needs Tint cards by quest type switched on."] = "Kartenfarbe für Schlachtzugseinträge. Erfordert die Aktivierung von „Karten nach Questtyp einfärben“."
L["Zone Progress Bar"] = "Gebietsfortschrittsleiste"
L["Show zone progress bar"] = "Gebietsfortschrittsleiste anzeigen"
L["Approximate questline progress."] = "Ungefährer Fortschritt der Questreihe."
L["Float as a movable bar"] = "Als verschiebbare Leiste anzeigen"
L["Drag to move, right-click to lock or reset. Unticked, the bar becomes an ordinary tracker section instead and only Bar Texture and Bar Color still apply to it."] = "Ziehen zum Verschieben, Rechtsklick zum Sperren oder Zurücksetzen. Wenn deaktiviert, wird die Leiste stattdessen zu einem gewöhnlichen Trackerabschnitt und nur „Leistentextur“ und „Leistenfarbe“ werden darauf angewendet."
L["Fills the floating bar behind its text."] = "Füllt die verschiebbare Leiste hinter ihrem Text aus."
L["Background color and opacity for the floating bar. While this is unset the bar uses a plain black fill that fades slightly once locked."] = "Hintergrundfarbe und Deckkraft der verschiebbaren Leiste. Solange keine Farbe festgelegt ist, verwendet die Leiste eine einfache schwarze Füllung, die nach dem Sperren leicht verblasst."
L["Draws a border around the floating bar."] = "Zeichnet einen Rand um die verschiebbare Leiste."
L["Border color and opacity for the floating bar."] = "Randfarbe und Deckkraft der verschiebbaren Leiste."
L["Zone Bar Scale"] = "Skalierung der Gebietsleiste"
L["Size of the floating bar. The docked section follows the tracker's own scale instead."] = "Größe der verschiebbaren Leiste. Der angedockte Abschnitt folgt stattdessen der eigenen Skalierung des Trackers."
L["Font for the floating bar's zone name, count and percentage. The docked section uses the tracker font."] = "Schriftart für Gebietsname, Anzahl und Prozentsatz der verschiebbaren Leiste. Der angedockte Abschnitt verwendet die Trackerschrift."
L["Bar Texture"] = "Leistentextur"
L["Sets the fill texture of the zone progress bar. Textures added by other media addons (such as SharedMedia, ElvUI, or Details) appear here too."] = "Legt die Fülltextur der Gebietsfortschrittsleiste fest. Von anderen Medien-Addons (wie SharedMedia, ElvUI oder Details) hinzugefügte Texturen werden hier ebenfalls angezeigt."
L["Fill color and opacity of the bar itself."] = "Füllfarbe und Deckkraft der Leiste selbst."
L["Header Color"] = "Überschriftenfarbe"
L["Color of the zone name on the floating bar. The docked section uses the section header color."] = "Farbe des Gebietsnamens auf der verschiebbaren Leiste. Der angedockte Abschnitt verwendet die Farbe der Abschnittsüberschrift."
L["Count Color"] = "Anzahlfarbe"
L["Color of the completed-of-total count on the floating bar."] = "Farbe der Anzahl abgeschlossener von insgesamt vorhandenen Quests auf der verschiebbaren Leiste."

